using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Services.Oficina;
public class OficinaService{readonly ErpDbContext _db;public OficinaService(ErpDbContext db)=>_db=db;
public async Task<OrdemServico> AbrirAsync(int clienteId,int? veiculoId,int km,string problema,string mecanico){var os=new OrdemServico{Numero=$"OS-{DateTime.Now:yyyyMMddHHmmss}",ClienteId=clienteId,VeiculoClienteId=veiculoId,Km=km,Problema=problema,Mecanico=mecanico};_db.OrdensServico.Add(os);await _db.SaveChangesAsync();return os;}
public async Task AdicionarPecaAsync(int osId,int produtoId,decimal qtd){if(qtd<=0)throw new InvalidOperationException("Quantidade inválida.");var os=await _db.OrdensServico.FindAsync(osId)??throw new InvalidOperationException("OS não encontrada.");if(os.Status=="FINALIZADA")throw new InvalidOperationException("OS finalizada.");var p=await _db.Produtos.FindAsync(produtoId)??throw new InvalidOperationException("Produto não encontrado.");_db.ItensOrdemServico.Add(new ItemOrdemServico{OrdemServicoId=osId,Tipo="PECA",ProdutoId=p.Id,Descricao=p.Descricao,Quantidade=qtd,ValorUnitario=p.PrecoVenda,Total=qtd*p.PrecoVenda});await Recalcular(os);await _db.SaveChangesAsync();}
public async Task AdicionarServicoAsync(int osId,string desc,decimal qtd,decimal valor){if(qtd<=0||valor<0)throw new InvalidOperationException("Quantidade/valor inválido.");var os=await _db.OrdensServico.FindAsync(osId)??throw new InvalidOperationException("OS não encontrada.");_db.ItensOrdemServico.Add(new ItemOrdemServico{OrdemServicoId=osId,Tipo="SERVICO",Descricao=desc,Quantidade=qtd,ValorUnitario=valor,Total=qtd*valor});await Recalcular(os);await _db.SaveChangesAsync();}
async Task Recalcular(OrdemServico os){var existentes=await _db.ItensOrdemServico.Where(x=>x.OrdemServicoId==os.Id).ToListAsync();var novos=_db.ChangeTracker.Entries<ItemOrdemServico>().Where(x=>x.State==EntityState.Added&&x.Entity.OrdemServicoId==os.Id).Select(x=>x.Entity);var todos=existentes.Concat(novos).Distinct();os.TotalPecas=todos.Where(x=>x.Tipo=="PECA").Sum(x=>x.Total);os.TotalServicos=todos.Where(x=>x.Tipo=="SERVICO").Sum(x=>x.Total);os.Total=os.TotalPecas+os.TotalServicos;}
public async Task FinalizarAsync(int osId,string usuario){await using var tx=await _db.Database.BeginTransactionAsync();var os=await _db.OrdensServico.Include(x=>x.Itens).SingleAsync(x=>x.Id==osId);if(os.Status=="FINALIZADA")throw new InvalidOperationException("OS já finalizada.");foreach(var i in os.Itens.Where(x=>x.Tipo=="PECA"&&x.ProdutoId!=null)){var p=await _db.Produtos.FindAsync(i.ProdutoId!.Value)??throw new InvalidOperationException("Produto inválido.");if(p.EstoqueAtual<i.Quantidade)throw new InvalidOperationException($"Estoque insuficiente: {p.Descricao}");var ant=p.EstoqueAtual;p.EstoqueAtual-=i.Quantidade;_db.MovimentacoesEstoque.Add(new MovimentacaoEstoque{ProdutoId=p.Id,Tipo="SAIDA_OS",Quantidade=i.Quantidade,SaldoAnterior=ant,SaldoPosterior=p.EstoqueAtual,Documento=os.Numero,Usuario=usuario});}os.EstoqueBaixado=true;os.Status="FINALIZADA";os.Finalizacao=DateTime.Now;if(!os.FinanceiroGerado){_db.ContasReceber.Add(new ContaReceber{ClienteId=os.ClienteId,Descricao=$"Ordem de Serviço {os.Numero}",Valor=os.Total,FormaPagamento="A DEFINIR",Status="ABERTO"});os.FinanceiroGerado=true;}_db.Auditorias.Add(new Auditoria{Data=DateTime.Now,Usuario=usuario,Acao="OS_FINALIZADA",Entidade="OrdemServico",Referencia=os.Numero,Detalhes=$"{os.Numero} - {os.Total:C}"});await _db.SaveChangesAsync();await tx.CommitAsync();}}